import { createHmac } from 'node:crypto';
import { hash, verify } from '@node-rs/argon2';
import { ARGON2_OPTIONS, PASSWORD_MAX_LENGTH, PASSWORD_MIN_LENGTH } from './constants';

/**
 * Argon2id with a unique per-hash random salt (generated by the library) and a
 * server-side pepper held only in an environment secret. The pepper is mixed via
 * HMAC-SHA256 BEFORE Argon2, so rotating the pepper never exposes the raw password
 * and the stored string remains a standard `$argon2id$...` encoding.
 */
export class PasswordHasher {
  private dummyHash: string | undefined;

  constructor(private readonly pepper: string) {}

  private peppered(password: string): string {
    return createHmac('sha256', this.pepper).update(password, 'utf8').digest('base64url');
  }

  async hashPassword(password: string): Promise<string> {
    return hash(this.peppered(password), ARGON2_OPTIONS);
  }

  async verifyPassword(passwordHash: string, password: string): Promise<boolean> {
    return verify(passwordHash, this.peppered(password));
  }

  /** Equalises timing for unknown identifiers; performs no DB work. */
  async dummyVerify(password: string): Promise<void> {
    if (this.dummyHash === undefined) {
      this.dummyHash = await hash(this.peppered('dummy-account-no-such-user'), ARGON2_OPTIONS);
    }
    await verify(this.dummyHash, this.peppered(password));
  }
}

export function assertPasswordPolicy(password: string): void {
  if (
    typeof password !== 'string' ||
    password.length < PASSWORD_MIN_LENGTH ||
    password.length > PASSWORD_MAX_LENGTH
  ) {
    throw new RangeError(
      `Password must be between ${PASSWORD_MIN_LENGTH} and ${PASSWORD_MAX_LENGTH} characters`
    );
  }
}
